"use strict";

// Turn an arbitrary title into a URL slug.
function slugify(title) {
  let slug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  // Keep a trailing numeric token (e.g. a year) underscored: -2026 -> _2026.
  const match = slug.match(/-\d+$/);
  if (match) {
    slug = slug.slice(0, match.index) + "_" + match[0].slice(1);
  }
  return slug;
}

module.exports = { slugify };

